// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Dünya mutfağı ve gastronomi terimleri (zor).
const ozCulture8Zor = <(String, String, List<String>, String)>[
  ('Patatesin yedi yüzlü, iki ucu sivri küçük bir fıçı biçiminde yontulmasına verilen ve beceri gerektiren kesimin adı nedir?', 'Tourné', ['Parisienne', 'Rondelle', 'Paysanne'], 'Tourné kesimde sebze, yedi kenarlı ve oval bir fıçı görünümünde yontulur; klasik Fransız mutfağında beceri ölçütü sayılır.'),
  ('Auguste Escoffier\'nin sınıflandırmasında beş ana sos sayılır. Aşağıdakilerden hangisi bu beş ana sostan biri değildir?', 'Mayonez', ['Velouté', 'Espagnole', 'Domates sosu'], 'Escoffier\'nin ana sosları beşamel, velouté, espagnole, hollandaise ve domates sosudur; mayonez soğuk bir emülsiyon olarak ayrı tutulur.'),
